        let long =
            combat_weapon(CheckedStrategicWeapon::admit(&item).unwrap(), Some(long)).unwrap();

        assert!((short.precision - 1.2).abs() < 1e-6);
        assert!((long.precision - 0.9).abs() < 1e-6);
