        striking_head_length_m: SignedLength,
        moment_of_inertia_kg_m2: f32,
        balance: f32,
        precision: f32,
    ) -> Option<Self> {
        let values = [mass_kg, moment_of_inertia_kg_m2, balance, precision];
        (values.into_iter().all(f32::is_finite)
            && mass_kg > 0.0
            && total_length_m.metres() > 0.0
            && grip_to_tip_m.metres() > 0.0
            && grip_to_tip_m.metres() <= total_length_m.metres()
            && (0.0..=total_length_m.metres()).contains(&striking_head_length_m.metres())
            && moment_of_inertia_kg_m2 >= 0.0
            && balance >= 0.0
            && precision >= 0.0)
            .then_some(Self {
                mass_kg,
                total_length_m,
                grip_to_tip_m,
                striking_head_length_m,
                moment_of_inertia_kg_m2,
                balance,
                precision,
            })
    }

    pub const fn melee_reach_m(self) -> SignedLength {
        self.grip_to_tip_m
    }

    /// Apply the existing edge-condition factor once to this instance's geometry.
    pub fn conditioned_precision(self, catalog_id: &str, effective_catalog_precision: f32) -> f32 {
        let base = crate::item_catalog::weapon_precision(catalog_id)
            .filter(|value| *value > 0.0)
            .expect("generated weapon has positive catalog precision");
        self.precision * effective_catalog_precision / base
    }
}
